From d9853de000d36dd300e4b29bce34779725438770 Mon Sep 17 00:00:00 2001
From: Harry King <d.harry.king@gmail.com>
Date: Wed, 19 Feb 2020 10:22:41 -0800
Subject: [PATCH] JS: fix bug in parsing a number in the time formats
 'hh:mm:ss' and 'hh:mm:ss.ssssss'

Fixes bug

Signed-off-by: Harry King <d.harry.king@gmail.com>

diff --git a/src/main/java/com/jaamsim/input/Input.java b/src/main/java/com/jaamsim/input/Input.java
index 614fdfe17..988ec072b 100644
--- a/src/main/java/com/jaamsim/input/Input.java
+++ b/src/main/java/com/jaamsim/input/Input.java
@@ -967,7 +967,7 @@ public abstract class Input<T> {
 			ret += hh * usPerHr;
 			ret += mm * usPerMin;
 			ret += ss * usPerSec;
-			return ret;
+			return ret * 1e-6;
 		}

 		if (isextendfull.matcher(input).matches()) {
@@ -995,7 +995,7 @@ public abstract class Input<T> {
 			ret += mm * usPerMin;
 			ret += ss * usPerSec;
 			ret += us;
-			return ret;
+			return ret * 1e-6;
 		}

 		throw new InputErrorException(INP_ERR_BADDATE, input);
-- 
2.48.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
JS: fix bug in parsing a number in the time formats
 'hh:mm:ss' and 'hh:mm:ss.ssssss'

Fixes bug

Signed-off-by: Harry King <d.harry.king@gmail.com>

Here is the root cause:
ss.ssssss' formats to be off by a factor of 1,000,000, leading to incorrect time values being used throughout the application. The fix multiplies the final result by `1e-6` to properly convert microseconds to seconds before returning.

Here is the patch:
 	 */
 	public static double parseRFC8601DateTime(JaamSimModel simModel, String input) {
 		if (isRFC8601Date(input)) {
 			int[] date = parseRFC8601Date(input);
 			long millis = simModel.getCalendarMillis(date[0], date[1] - 1, date[2], date[3], date[4], date[5], date[6]);
 			return simModel.calendarMillisToSimTime(millis);
 		}

 		if (isextendtime.matcher(input).matches()) {
 			int len = input.length();
 			int hh = Integer.parseInt(input.substring(0, len - 6));
 			int mm = Integer.parseInt(input.substring(len - 5, len - 3));
 			int ss = Integer.parseInt(input.substring(len - 2, len));

 			if (mm < 0 || mm > 59 || ss < 0 || ss > 59)
 				throw new InputErrorException(INP_ERR_BADDATE, input);

 			long ret = 0;
 			ret += hh * usPerHr;
 			ret += mm * usPerMin;
 			ret += ss * usPerSec;
-			return ret;
+			return ret * 1e-6;
 		}

 		if (isextendfull.matcher(input).matches()) {
 			int len = input.indexOf('.');
 			int hh = Integer.parseInt(input.substring(0, len - 6));
 			int mm = Integer.parseInt(input.substring(len - 5, len - 3));
 			int ss = Integer.parseInt(input.substring(len - 2, len));

 			if (mm < 0 || mm > 59 || ss < 0 || ss > 59)
 				throw new InputErrorException(INP_ERR_BADDATE, input);

 			// grab the us values and zero-pad to a full 6-digit number
 			String usChars =  input.substring(len + 1, input.length());
 			int us = 0;
 			switch (usChars.length()) {
 			case 1: us =  Integer.parseInt(usChars) * 100000; break;
 			case 2: us =  Integer.parseInt(usChars) *  10000; break;
 			case 3: us =  Integer.parseInt(usChars) *   1000; break;
 			case 4: us =  Integer.parseInt(usChars) *    100; break;
 			case 5: us =  Integer.parseInt(usChars) *     10; break;
 			case 6: us =  Integer.parseInt(usChars) *      1; break;
 			}
 			long ret = 0;
 			ret += hh * usPerHr;
 			ret += mm * usPerMin;
 			ret += ss * usPerSec;
 			ret += us;
-			return ret;
+			return ret * 1e-6;
 		}

 		throw new InputErrorException(INP_ERR_BADDATE, input);
 	}



